<?php
$tournament = $params['tournament'];
$exists = KickoffTournament::exists($tournament);
$seeds = KickoffTournament::availableSeeds();
$imported = KickoffTournament::importedTournaments();
$info = $exists ? KickoffTournament::get($tournament) : array();
$type = $exists ? KickoffTournament::predictionType($tournament) : 'score';
$teams = $exists ? KickoffTournament::teams($tournament) : array();
$matches = $exists ? KickoffTournament::matches($tournament) : array();
$results = $exists ? KickoffTournament::results($tournament) : array('results' => array());
$resultMap = isset($results['results']) ? $results['results'] : array();
$leaderboard = $exists ? KickoffLeaderboard::get($tournament) : array('rows' => array(), 'updated' => '');
$predictionStats = $exists ? KickoffPrediction::predictionStats($tournament) : array('players' => 0, 'predictions' => 0, 'bonus_players' => 0);
$predictionRows = $exists ? KickoffPrediction::overviewRows($tournament, $matches, $teams, 200) : array();
$completed = 0;
$groups = array();
$dates = array();
foreach ($matches as $m) {
    if (!empty($m['group'])) { $groups[$m['group']] = $m['group']; }
    if (!empty($m['kickoff'])) { $dates[date('Y-m-d', strtotime($m['kickoff']))] = date('Y-m-d', strtotime($m['kickoff'])); }
    if (isset($resultMap[$m['id']])) {
        $r = $resultMap[$m['id']];
        if (($type === 'pick_winner' && !empty($r['winner_id'])) || ($type !== 'pick_winner' && isset($r['home_score']) && isset($r['away_score']))) { $completed++; }
    }
}
sort($groups); sort($dates);
$totalMatches = count($matches);
$totalTeams = count($teams);
$totalPlayers = isset($leaderboard['rows']) && is_array($leaderboard['rows']) ? count($leaderboard['rows']) : 0;
$publicUrl = $exists ? kickoff_url('home', $tournament) : '';
?>
